// LUT for extracting registers according to format.
extract_reg_func_t extract_regs_table[NUM_FORMATS];

/*
 * Control signals for D, X, M, and W stages.
 * Generated by D stage logic.
 * D control signals are consumed locally.
 * Others must be buffered in pipeline registers.
 * STUDENT TO-DO:
 * Generate the correct control signals for this instruction's
 * future stages and write them to the corresponding struct.
 */
static comb_logic_t generate_DXMW_control(opcode_t op, d_ctl_sigs_t *D_sigs,
                                          x_ctl_sigs_t *X_sigs,
                                          m_ctl_sigs_t *M_sigs,
                                          w_ctl_sigs_t *W_sigs) {
    // Student TODO
    D_sigs->src2_sel = (op == OP_STUR);
    
    // check if using multipurpose val for adrp instead of vala
    X_sigs->vala_sel = (op == OP_ADRP);
    // check if using reg for valb (or for ret (b3))
    X_sigs->valb_sel = (op == OP_ADDS_RR || op == OP_SUBS_RR || op == OP_CMP_RR || 
                        op == OP_CMN_RR || op == OP_ORR_RR || op == OP_EOR_RR || 
                        op == OP_ANDS_RR || op == OP_TST_RR || op == OP_LSL_RR || 
                        op == OP_LSR_RR || op == OP_RET || op == OP_MVN); 
    // check if setting nzcv flags                   
    //X_sigs->set_flags = (op == OP_ADDS_RR || op == OP_SUBS_RR || op == OP_ANDS_RR);
    X_sigs->set_flags = (op == OP_ADDS_RR || op == OP_SUBS_RR || op == OP_ANDS_RR ||
                        op == OP_CMP_RR || op == OP_CMN_RR || op == OP_TST_RR);

    // mem signals
    M_sigs->dmem_read = (op == OP_LDUR);
    M_sigs->dmem_write = (op == OP_STUR);

    // check if writing to x30
    W_sigs->dst_sel = (op == OP_BL);
    // check if write val comes from mem
    W_sigs->wval_sel = (op == OP_LDUR);
    // enable write for any instr that modifies a reg
    W_sigs->w_enable = (op == OP_LDUR || op == OP_MOVZ || op == OP_MOVK || 
                        op == OP_ADRP || op == OP_ADD_RI || op == OP_ADDS_RR || 
                        op == OP_SUB_RI || op == OP_SUBS_RR || op == OP_ORR_RR || 
                        op == OP_EOR_RR || op == OP_ANDS_RR || op == OP_LSL_RI || 
                        op == OP_LSR_RI || op == OP_LSL_RR || op == OP_LSR_RR || 
                        op == OP_ASR || op == OP_BL || op == OP_MVN);
    return;
}

/*
 * Logic for extracting the immediate value for M-, I-, and RI-format
 * instructions.
 * STUDENT TO-DO:
 * Extract the immediate value and write it to *imm.
 */
static comb_logic_t extract_immval(uint32_t insnbits, opcode_t op,
                                   int64_t *imm) {
    // Student TODO
    switch (op)
    {
    // M
    case OP_LDUR:
    case OP_STUR:
        *imm = bitfield_s64(insnbits, 12, 9);
        break;
    // I1
    case OP_MOVK:
    case OP_MOVZ:
        *imm = bitfield_u32(insnbits, 5, 16);
        break;
    // I2
    case OP_ADRP:
        int64_t immhi = bitfield_s64(insnbits, 5, 19);
        uint64_t immlo = bitfield_u32(insnbits, 29, 2);
        // int64_t combined = (immhi << 2) | immlo;
        // combined = (combined << 43) >> 43;
        // *imm = combined << 12;
        *imm = ((immhi << 2) | (int64_t)immlo) << 12;
        break;
    // RI (arithmetic)
    case OP_ADD_RI:
    case OP_SUB_RI:
        *imm = bitfield_u32(insnbits, 10, 12);
        break;
    // RI (logical)
    
    case OP_ASR:
    case OP_LSR_RI:
        *imm = bitfield_u32(insnbits, 16, 6);
        break;
    case OP_LSL_RI:
        *imm = 63 - bitfield_u32(insnbits, 10, 6);
        break;
    default:
        *imm = 0;
        break;
    }
    return;
}

/*
 * Logic for determining the ALU operation needed for this opcode.
 * STUDENT TO-DO:
 * Determine the ALU operation based on the given opcode
 * and write it to *ALU_op.
 */
static comb_logic_t decide_alu_op(opcode_t op, alu_op_t *ALU_op) {
    // Student TODO
    switch(op){
        case OP_ADD_RI:
        case OP_ADDS_RR:
        case OP_CMN_RR:
        // address calc
        case OP_LDUR:
        case OP_STUR:
            *ALU_op = PLUS_OP;
            break;
        
        case OP_SUB_RI:
        case OP_SUBS_RR:
        case OP_CMP_RR:
            *ALU_op = MINUS_OP;
            break;
        
        case OP_MVN:
            *ALU_op = INV_OP;
            break;
        
        case OP_MOVZ:
            *ALU_op = MOV_OP;
            break;
        case OP_MOVK:
            *ALU_op = MOVK_OP;
            break;
        
        case OP_ANDS_RR:
        case OP_TST_RR:
            *ALU_op = AND_OP;
            break;
        case OP_ORR_RR:
            *ALU_op = OR_OP;
            break;
        case OP_EOR_RR:
            *ALU_op = EOR_OP;
            break;
        
        case OP_LSL_RI:
        case OP_LSL_RR:
            *ALU_op = LSL_OP;
            break;
        case OP_LSR_RI:
        case OP_LSR_RR:
            *ALU_op = LSR_OP;
            break;
        case OP_ASR:
            *ALU_op = ASR_OP;
            break;
        
        default:
            *ALU_op = PASS_A_OP;
    }
    return;
}

